// CUPÓN CACHÉ: cada consulta lleva el MISMO manual con el MISMO señalador.
// Es lo que ya quedó sobre el escritorio, así Claude lo encuentra abierto
// y lo cobra 10 veces más barato.
const manual = $('El manual (parte fija)').first().json.parte_fija;

// Las consultas que pasaron el filtro. Cada correo de Gmail trae
// el remitente (from.text), la fecha (date) y el texto (text).
const requests = $input.all().map((correo, i) => ({
  // La etiqueta de cada consulta: las respuestas del lote vuelven mezcladas.
  custom_id: 'consulta-' + (i + 1),
  params: {
    model: 'claude-sonnet-5',
    max_tokens: 1024,
    thinking: { type: 'disabled' },
    // El manual + el señalador (cache_control). 1 hora, porque el lote puede tardar.
    system: [{ type: 'text', text: manual, cache_control: { type: 'ephemeral', ttl: '1h' } }],
    // Después del señalador, lo que cambia: la plantilla de la Guía 1 con este correo.
    messages: [{
      role: 'user',
      content: 'Remitente: ' + correo.json.from.text + '\nFecha: ' + correo.json.date + '\nConsulta:\n' + correo.json.text
    }]
  }
}));

// Todas las consultas del mes van en UN solo paquete.
return [{ json: { paquete: { requests } } }];

// Las respuestas llegan en formato JSONL: una línea por consulta.
// Como en la Semana 5 (Parse JSON), cada respuesta es una maleta cerrada:
// un texto con el JSON adentro. Acá la abrimos para usar sus campos.
const correos = $('No es respuesta automática').all();
const lineas = ($input.first().json.data || '').split('\n').filter(l => l.trim());

return lineas.map(linea => {
  const r = JSON.parse(linea);
  const n = Number(r.custom_id.split('-')[1]) - 1;   // consulta-1 es el correo 0
  const mensaje = (r.result && r.result.message) || {};

  let datos = {};
  try {
    const texto = (mensaje.content || []).map(b => b.text || '').join('');
    datos = JSON.parse(texto.replace(/```json|```/g, '').trim());
  } catch (e) {
    datos = { servicio: 'Sin respuesta', resumen: 'Revisar a mano: ' + r.custom_id };
  }

  return { json: {
    quien: correos[n] ? correos[n].json.from.text : r.custom_id,
    servicio: datos.servicio,
    presupuesto_usd: datos.presupuesto_usd,
    prioridad: datos.prioridad,
    resumen: datos.resumen,
    factura: mensaje.usage || {}
  } };
});

// Arma el correo para Paula con las tres preguntas del reporte:
// qué servicios piden, con qué presupuesto y con qué urgencia.
const consultas = $input.all().map(i => i.json);
const cantidad = consultas.length;

// 1. Qué servicios piden
const porServicio = {};
consultas.forEach(c => { porServicio[c.servicio] = (porServicio[c.servicio] || 0) + 1; });
const servicios = Object.entries(porServicio).sort((a, b) => b[1] - a[1])
  .map(([s, n]) => '- ' + s + ': ' + n).join('\n');

// 2. Con qué presupuesto (solo las que mencionan un monto)
const conMonto = consultas.filter(c => typeof c.presupuesto_usd === 'number');
const totalMonto = conMonto.reduce((t, c) => t + c.presupuesto_usd, 0);

// 3. Con qué urgencia
const urgentes = consultas.filter(c => c.prioridad === 5);
const medias = consultas.filter(c => c.prioridad === 3 || c.prioridad === 4);
const bajas = consultas.filter(c => c.prioridad === 1 || c.prioridad === 2);

// La factura: cuánto costó el reporte con los dos cupones y cuánto habría costado sin ellos.
// Precios de Claude Sonnet 5 por millón de tokens (verificados el 28/09/2026).
// Sin cupones: entrada 2, salida 10. En lote: entrada 1, salida 5,
// lectura del escritorio 0,10, guardar 1 hora 2. Poner el manual sobre el escritorio: 4.
let sin = 0, con = 0;
consultas.forEach(c => {
  const u = c.factura;
  const entrada = u.input_tokens || 0, guardados = u.cache_creation_input_tokens || 0;
  const leidos = u.cache_read_input_tokens || 0, salida = u.output_tokens || 0;
  sin += ((entrada + guardados + leidos) * 2 + salida * 10) / 1e6;
  con += (entrada * 1 + guardados * 2 + leidos * 0.1 + salida * 5) / 1e6;
});
const u0 = $('Poner el manual sobre el escritorio').first().json.usage || {};
const escritorio = ((u0.input_tokens || 0) * 2 + (u0.cache_creation_input_tokens || 0) * 4) / 1e6;
con += escritorio;
const deCada100 = Math.round(con / sin * 100);
// Con 600 consultas, el manual se pone sobre el escritorio una sola vez y se reparte entre todas.
const con600 = Math.round((escritorio + (con - escritorio) / cantidad * 600) / (sin / cantidad * 600) * 100);
const usd = n => 'US$ ' + n.toFixed(4).replace('.', ',');

const mensaje = [
  'Hola Paula, este es el reporte de las consultas del último mes.',
  '',
  'Consultas analizadas: ' + cantidad,
  '',
  'QUÉ SERVICIOS PIDEN',
  servicios,
  '',
  'CON QUÉ PRESUPUESTO',
  '- Mencionan un monto: ' + conMonto.length + ' de ' + cantidad + ' (en total, USD ' + totalMonto + ')',
  '',
  'CON QUÉ URGENCIA',
  '- Quieren avanzar ya (prioridad 5): ' + urgentes.length,
  '- Interés concreto, sin apuro (3 o 4): ' + medias.length,
  '- Solo averiguan (1 o 2): ' + bajas.length,
  '',
  'LAS MÁS URGENTES',
  urgentes.map(c => '- ' + c.quien + ': ' + c.resumen).join('\n') || '- Ninguna',
  '',
  'LO QUE COSTÓ ESTE REPORTE (Claude Sonnet 5, con caché y lote)',
  '- Sin cupones: ' + usd(sin) + '. Con los dos cupones: ' + usd(con) + '.',
  '- De cada 100, pagamos ' + deCada100 + '. Con 600 consultas pagaríamos unos ' + con600 + '.',
  '',
  '(Reporte automático)'
].join('\n');

return [{ json: { asunto: 'Reporte mensual de consultas - Agencia Norte', mensaje } }];
